import {timingSettings} from './timing.js?v=20261008-identity';
const $=s=>document.querySelector(s);
export function mountTiming(api){const card=document.createElement('div');card.className='timing-card';card.innerHTML=`<h3>Lap detection & sectors</h3><p class="field-hint">Start/finish starts the lap. Cross S1, then S2, then start/finish to complete it. Dashed teal gates show the exported split locations.</p><label>Split placement<select id="timing-mode"><option value="auto">Automatic · prefer straights</option><option value="manual">Custom lap percentages</option></select></label><div class="studio-fields"><label>S1 · % of lap<input id="timing-split1" type="number" min="10" max="80" step=".1"></label><label>S2 · % of lap<input id="timing-split2" type="number" min="20" max="90" step=".1"></label></div><div id="timing-lengths" class="sector-lengths"></div><button id="timing-start" class="outline-button">Place start / finish on road</button><p class="field-hint">All three sectors must be at least 10% of the lap. Gates, AI progress and exported sector labels share the same start point.</p>`;
 $('#ac-design-pits').closest('.ac-group').after(card);
 $('#timing-mode').onchange=()=>api.updateTrack(t=>t.timing={...timingSettings(t),mode:$('#timing-mode').value});
 const edit=()=>{const split1=Number($('#timing-split1').value)/100,split2=Number($('#timing-split2').value)/100;if(!Number.isFinite(split1)||!Number.isFinite(split2)||split1<.1||split1>.8||split2>.9||split2-split1<.1-1e-9){api.toast('Place S1 and S2 in order, with at least 10% of the lap in every sector.');refresh();return;}api.updateTrack(t=>t.timing={mode:'manual',split1,split2});};$('#timing-split1').onchange=edit;$('#timing-split2').onchange=edit;
 $('#timing-start').onclick=()=>{api.editView();api.setTool('start');api.toast('Click the road to position start / finish. Sector progress follows the new start.');};
 function refresh(){const t=api.getTrack(),settings=timingSettings(t),plan=api.getTimingPlan();$('#timing-mode').value=settings.mode;$('#timing-split1').value=(plan.splits[0]*100).toFixed(1);$('#timing-split2').value=(plan.splits[1]*100).toFixed(1);for(const id of ['#timing-split1','#timing-split2'])$(id).disabled=settings.mode!=='manual';$('#timing-lengths').innerHTML=plan.sectorLengths.map((length,i)=>`<span>Sector ${i+1}<b>${Math.round(length)} m</b></span>`).join('');$('#timing-start').disabled=t.points.length<3;}
 return {refresh};
}
